      "instructions": [
        {
          "instruction_ref": "format_reply",
          "opcode": "format_alert_outcome",
          "inputs": [
            {
              "type": "result",
              "identifier": "raw_message"
            },
            {
              "type": "result",
              "identifier": "slack_receipt"
            },
            {
              "type": "result",
              "identifier": "skip_note"
            }
          ],
          "outputs": [
