      "source_block_ref": "read_input",
      "target_block_ref": "decide"
    },
    {
      "source_block_ref": "decide",
      "target_block_ref": "send_alert",
      "condition_text": "urgent"
    },
    {
      "source_block_ref": "decide",
      "target_block_ref": "skip_alert",
      "condition_text": "not urgent"
    },
    {
      "source_block_ref": "send_alert",
      "target_block_ref": "reply"
    },
    {
      "source_block_ref": "skip_alert",
      "target_block_ref": "reply"
    }
  ],
  "diagnostics": []
}

